// Package emit turns Phaenon source into PHP source.
//
// The emitter is patch-based: the output is the input text with a list of
// span edits applied. Everything the emitter has no reason to touch —
// comments, formatting, code that is already plain PHP — passes through byte
// for byte; the emitter is not a formatter.
//
// What the compiler writes or rewrites it lays out as PER Coding Style 3.0
// wants it (design/line-map.md §2, roadmap D19, D22): the open tag, the
// @generated marker and declare(strict_types=1) on lines of their own; the
// imports it adds on lines of their own in the file's use block; the
// docblocks it writes or extends as multi-line blocks, one tag per line; an
// expression body as a block; the opening brace of a named function, method
// or class-like on the next line (after a multi-line parameter list, on the
// `)` line), an empty body `{}` left on the declaration's line; the arrow
// functions it writes as `fn(`, its closures' blocks on lines of their own.
// __LINE__ becomes the source line as a literal.
//
// Line N of the output is therefore not line N of the .phn. Every edit is
// either in place — its text has as many line breaks as the span it
// replaces, standing for them — or free, laying out lines of its own; the
// writer follows the origin of every output byte through both kinds and
// ends the file with a line map (package linemap) of runs and holds: the
// lines the compiler wrote are holds, so the tools that translate positions
// (phn trace, the PhpStorm plugin, phaenon/runtime) never put a breakpoint
// on them.
//
// Phaenon constructs that need rewriting (generics erasure, is/as, …) are
// further edits; the printer renders synthesised fragments, which are then
// spliced in by this package.
package emit

import (
	"bytes"
	"fmt"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"

	"github.com/phaenonlang/phaenon/internal/ast"
	"github.com/phaenonlang/phaenon/internal/lexer"
	"github.com/phaenonlang/phaenon/internal/linemap"
	"github.com/phaenonlang/phaenon/internal/parser"
	"github.com/phaenonlang/phaenon/internal/program"
	"github.com/phaenonlang/phaenon/internal/token"
)

// Marker is the comment that identifies generated output; it is the first
// thing after the open tag of an emitted file. Tools (phn migrate, phn build
// --clean) use it to tell generated .php files from hand-written ones.
const Marker = "@generated by phaenon"

// Options control emission.
type Options struct {
	// SourceName is the .phn path recorded in the marker (base name only).
	SourceName string
	// MapSource is the .phn path the line map names, relative to the
	// directory of the compiled file, with `/` separators. Empty, it is the
	// base name of SourceName: the path of an output written beside its
	// source.
	MapSource string
	// NoMap leaves the line map out, for compiled files shipped without
	// their sources (phn stdlib): their positions are meant as PHP.
	NoMap bool
	// StrictTypes injects declare(strict_types=1) unless the file declares
	// strict_types itself. Phaenon is strict by default; the conformance
	// suite turns this off to compare against non-strict PHP tests.
	StrictTypes bool
	// Program and File carry the type information generics need (the
	// checked program and this file's entry in it). A file that uses
	// Phaenon type syntax cannot be compiled without them.
	Program *program.Program
	File    *program.File
}

// Error is an emission error at a source position.
type Error struct {
	File string
	Line int
	Msg  string
}

func (e *Error) Error() string {
	if e.File == "" {
		return fmt.Sprintf("line %d: %s", e.Line, e.Msg)
	}
	return fmt.Sprintf("%s:%d: %s", e.File, e.Line, e.Msg)
}

// File compiles one .phn source to PHP.
func File(src []byte, opts Options) ([]byte, error) {
	out, _, err := FileVerbatim(src, opts)
	return out, err
}

// Verbatim is a run of the output copied from the source byte for byte:
// source offsets [Src, Src+Len) at output offset Out. An output's verbatim
// spans are the complement of the emitter's edits and of the indentation it
// adds, and the source's runs inside a folded pipe's text, which moves its
// operands (fold.go); everything between them is text the compiler wrote.
// phn fix carries a tool's change of the output back to the source through
// them (design/tooling.md §4).
type Verbatim struct {
	Src, Out, Len int
}

// FileVerbatim is File with the output's verbatim spans, in output order,
// two spans never adjacent on both sides and never sharing a source byte.
// A moved span breaks the source order of the others.
func FileVerbatim(src []byte, opts Options) ([]byte, []Verbatim, error) {
	f := (*ast.File)(nil)
	if opts.File != nil && opts.File.AST != nil {
		// The checker's tree: its records (method targets, …) key on nodes.
		f = opts.File.AST
	} else {
		var err error
		if f, err = parser.Parse(src, lexer.ModePhaenon); err != nil {
			if pe, ok := err.(*parser.Error); ok {
				return nil, nil, &Error{File: opts.SourceName, Line: pe.Line, Msg: pe.Msg}
			}
			return nil, nil, err
		}
	}
	out, w, err := compile(src, f, opts)
	if err != nil {
		return nil, nil, err
	}
	return out, w.verbatim(), nil
}

// Tree compiles an already parsed file. src must be the text f was parsed from.
func Tree(src []byte, f *ast.File, opts Options) ([]byte, error) {
	out, _, err := compile(src, f, opts)
	return out, err
}

// compile is Tree with the writer, whose copied source segments the tests
// check the line map against.
func compile(src []byte, f *ast.File, opts Options) ([]byte, *lineWriter, error) {
	e := &emitter{src: src, opts: opts, throwsWritten: map[ast.Node]bool{}}
	e.planIndents(f)
	if err := e.lowerGenerics(f); err != nil {
		return nil, nil, err
	}
	e.lowerFunctions(f)
	e.lowerConcurrency(f)
	if opts.File != nil {
		e.translateWrittenDocs()
	}
	e.lowerLine(f)
	if err := e.lowerTarget(f); err != nil {
		return nil, nil, err
	}
	e.prologue(f)
	out, w := e.apply()
	return out, w, nil
}

// IsGenerated reports whether src is an emitted file: the marker comment is
// the first thing after its open tag (on the open tag's line before D19, on
// a line of its own since).
func IsGenerated(src []byte) bool {
	rest, ok := bytes.CutPrefix(src, []byte("<?php"))
	if !ok {
		return false
	}
	rest = bytes.TrimLeft(rest, " \t\r\n")
	return bytes.HasPrefix(rest, []byte("/* "+Marker))
}

// ------------------------------------------------------------------ edits

// edit replaces src[Start:End) with Text. An in-place edit (Free false)
// has as many line breaks as the span it replaces, standing for them; a
// free edit lays out lines of its own, which the line map holds to the
// source line it starts on. Early puts an insertion ahead of every other
// edit at its offset (an import before a generated docblock). mapHere
// marks where the line map goes in a file that uses __halt_compiler().
type edit struct {
	ast.Span
	Text    string
	Early   bool
	Free    bool
	mapHere bool
	// Owner is the node whose lowering wrote an insertion at its end, so
	// that text moved with the node keeps it (renderSpan); zero otherwise.
	Owner ast.Span
	// Pieces are the runs of a free edit's text copied from the source
	// byte for byte, the operands a folded pipe moves: the source's text
	// where it lands, so phn fix carries a change of it back (Verbatim).
	Pieces []piece
}

// piece is a run of an edit's text, at offset Off in it, that holds the
// source bytes of Span.
type piece struct {
	Off int
	ast.Span
}

type emitter struct {
	src   []byte
	opts  Options
	edits []edit
	// indents are the continuation lines expanded expression bodies move in.
	indents []indentReq
	// drop are the spans of statements and attribute groups the compiler
	// removes (dropLines).
	drop []ast.Span
	// header is the text before the source: open tag, marker, declare.
	header string
	// imports are the classes the compiler introduced, by fully qualified
	// name, with the short name each is called by in this file ("" when the
	// name is taken and the FQCN is used): roadmap D11.
	imports map[string]string
	// ownImports are the compiler-introduced classes the file already
	// imports itself: used by their alias, not added to the use list.
	ownImports map[string]bool
	// qualifiedHeads are the first segments of the qualified names the file
	// writes, lower-cased: names an import of the same short name would
	// re-resolve (qualifiedHead).
	qualifiedHeads map[string]bool
	// throwsWritten are the declarations whose `throws` clause the generics
	// lowering wrote into the docblock it generated (addDocWith).
	throwsWritten map[ast.Node]bool
	// toks is the source's token stream, read when an edit needs a
	// position the tree does not keep (layout.go).
	toks []token.Token
}

// replace is an in-place edit: text keeps the span's line breaks.
func (e *emitter) replace(s ast.Span, text string) {
	if got, want := strings.Count(text, "\n"), bytes.Count(e.src[s.Start:s.End], []byte("\n")); got != want {
		panic(fmt.Sprintf("emit: in-place edit at %d changes the line count (%d → %d), make it free: %q", s.Start, want, got, text))
	}
	e.edits = append(e.edits, edit{Span: s, Text: text})
}

func (e *emitter) insert(at int, text string) {
	e.replace(ast.Span{Start: at, End: at}, text)
}

// insertEnd is an in-place insertion at the end of the node owner whose
// lowering it belongs to.
func (e *emitter) insertEnd(owner ast.Span, text string) {
	e.replace(ast.Span{Start: owner.End, End: owner.End}, text)
	e.edits[len(e.edits)-1].Owner = owner
}

// insertEndFree is a free insertion at the end of the node owner whose
// lowering it belongs to.
func (e *emitter) insertEndFree(owner ast.Span, text string) {
	e.replaceFree(ast.Span{Start: owner.End, End: owner.End}, text)
	e.edits[len(e.edits)-1].Owner = owner
}

// replaceFree is a free edit: text the compiler lays out, whose line breaks
// are its own; the span's line breaks go.
func (e *emitter) replaceFree(s ast.Span, text string) {
	e.edits = append(e.edits, edit{Span: s, Text: text, Free: true})
}

func (e *emitter) insertFree(at int, text string) {
	e.replaceFree(ast.Span{Start: at, End: at}, text)
}

// apply splices the edits into the source behind the header and appends
// the line map. Edits must not overlap. At one offset, early insertions
// come first, then the other insertions, then a replacement starting
// there; insertions of a kind keep their order of registration.
func (e *emitter) apply() ([]byte, *lineWriter) {
	sort.SliceStable(e.edits, func(i, j int) bool { return editLess(e.edits[i], e.edits[j]) })
	w := newLineWriter(e.src, e.indents)
	w.free(e.header, 0)
	pos := 0
	for _, ed := range e.edits {
		if ed.Start < pos {
			panic(fmt.Sprintf("emit: overlapping edits in %s at line %d: %q", e.opts.SourceName, e.lineOf(ed.Start), ed.Text))
		}
		w.source(pos, ed.Start)
		switch {
		case ed.mapHere:
			if ed.Text != "" {
				w.free(ed.Text, ed.Start)
			}
			w.markMap(ed.Start)
		case ed.Free:
			w.freeWith(ed.Text, ed.Start, ed.Pieces)
		default:
			w.inPlace(ed.Text, ed.Span)
		}
		pos = ed.End
	}
	w.source(pos, len(e.src))
	source := e.mapSource()
	if e.opts.NoMap || source == "" {
		return w.out.Bytes(), w
	}
	if w.mapAt >= 0 {
		// Before __halt_compiler(): what follows is data and stays as written.
		line := linemap.Build(source, w.classify()).String() + "\n"
		w.insertedAt, w.inserted = w.mapAt, len(line)
		out := w.out.Bytes()
		return append(out[:w.mapAt:w.mapAt], append([]byte(line), out[w.mapAt:]...)...), w
	}
	// A .phn is PHP code to its end (Phaenon has no close tag), so the map
	// never needs the `<?php ` spelling an inline-HTML ending would.
	if out := w.out.Bytes(); len(out) > 0 && out[len(out)-1] != '\n' {
		w.free("\n", len(e.src))
	}
	w.out.WriteString(linemap.Build(source, w.classify()).String() + "\n")
	return w.out.Bytes(), w
}

// editLess orders edits as apply writes them: by offset, and at one
// offset early insertions, then the other insertions, then a replacement.
func editLess(a, b edit) bool {
	if a.Start != b.Start {
		return a.Start < b.Start
	}
	if a.Early != b.Early {
		return a.Early
	}
	return a.Start == a.End && b.Start != b.End
}

// spliced is the source with the edits applied and nothing else: the text
// of a docblock a lowering rewrites on a scratch emitter.
func (e *emitter) spliced() []byte {
	sort.SliceStable(e.edits, func(i, j int) bool { return e.edits[i].Start < e.edits[j].Start })
	var out bytes.Buffer
	pos := 0
	for _, ed := range e.edits {
		out.Write(e.src[pos:ed.Start])
		out.WriteString(ed.Text)
		pos = ed.End
	}
	out.Write(e.src[pos:])
	return out.Bytes()
}

// mapSource is the path the line map names, "" when there is none to name.
func (e *emitter) mapSource() string {
	if e.opts.MapSource != "" {
		return e.opts.MapSource
	}
	if e.opts.SourceName == "" {
		return ""
	}
	return filepath.Base(e.opts.SourceName)
}

func (e *emitter) lineOf(offset int) int {
	return 1 + bytes.Count(e.src[:offset], []byte("\n"))
}

func (e *emitter) errorf(n ast.Node, format string, args ...any) error {
	return &Error{File: e.opts.SourceName, Line: e.lineOf(n.Span().Start), Msg: fmt.Sprintf(format, args...)}
}

// tokens is the source's token stream, read once.
func (e *emitter) tokens() []token.Token {
	if e.toks == nil {
		e.toks = lexer.Tokenize(e.src, lexer.ModePhaenon)
	}
	return e.toks
}

// ------------------------------------------------------------------ passes

// prologue writes the header — the open tag, the marker and (unless the
// file has its own) declare(strict_types=1), each on a line of its own and
// separated by blank lines — places the compiler's imports, and marks
// where the line map goes in a file that uses __halt_compiler().
func (e *emitter) prologue(f *ast.File) {
	var sb strings.Builder
	sb.WriteString("<?php\n\n/* ")
	sb.WriteString(Marker)
	if e.opts.SourceName != "" {
		sb.WriteString(" from ")
		sb.WriteString(filepath.Base(e.opts.SourceName))
	}
	sb.WriteString(" */\n")
	if e.opts.StrictTypes && !declaresStrictTypes(f) {
		sb.WriteString("\ndeclare(strict_types=1);\n")
	}
	// A blank line before the source's first line, unless the source opens
	// with one itself (or is empty).
	if len(bytes.TrimLeft(e.src, " \t\r")) > 0 && bytes.TrimLeft(e.src, " \t\r")[0] != '\n' {
		sb.WriteString("\n")
	}
	e.header = sb.String()
	e.dropLines()
	for _, s := range e.importSites(f) {
		e.edits = append(e.edits, edit{Span: s.span, Text: s.text, Early: true, Free: true})
	}
	if h := haltStatement(f); h != nil {
		at := bytes.LastIndexByte(e.src[:h.S.Start], '\n') + 1
		text := ""
		if len(bytes.TrimSpace(e.src[at:h.S.Start])) > 0 {
			at, text = h.S.Start, "\n" // code before it on its line
		}
		e.edits = append(e.edits, edit{Span: ast.Span{Start: at, End: at}, Text: text, mapHere: true})
	}
}

// dropLines removes the statements and attribute groups the compiler
// drops — a type alias, an attribute the target does not have. One that
// fills its lines goes with them, a run of them together, and with a blank
// line that would otherwise follow a blank line; one that shares its line
// with code goes, and its line breaks stay.
func (e *emitter) dropLines() {
	sort.Slice(e.drop, func(i, j int) bool { return e.drop[i].Start < e.drop[j].Start })
	src := e.src
	var whole []ast.Span
	for _, s := range e.drop {
		start, end := s.Start, s.End
		for start > 0 && (src[start-1] == ' ' || src[start-1] == '\t') {
			start--
		}
		for end < len(src) && (src[end] == ' ' || src[end] == '\t' || src[end] == '\r') {
			end++
		}
		if (start > 0 && src[start-1] != '\n') || (end < len(src) && src[end] != '\n') {
			// Code shares the line: the text and the spaces after it go, the
			// indentation and the line breaks stay.
			start, end = s.Start, s.End
			for end < len(src) && (src[end] == ' ' || src[end] == '\t') {
				end++
			}
			e.replace(ast.Span{Start: start, End: end}, strings.Repeat("\n", bytes.Count(src[start:end], []byte("\n"))))
			continue
		}
		if end < len(src) {
			end++ // the line break
		}
		if n := len(whole); n > 0 && whole[n-1].End == start {
			whole[n-1].End = end
			continue
		}
		whole = append(whole, ast.Span{Start: start, End: end})
	}
	for _, s := range whole {
		// A blank line before and after: the one after goes too.
		if blankLineAt(src, lineBefore(src, s.Start)) && s.End < len(src) && blankLineAt(src, s.End) {
			if nl := bytes.IndexByte(src[s.End:], '\n'); nl >= 0 {
				s.End += nl + 1
			}
		}
		e.replaceFree(s, "")
	}
}

// lineBefore is the start of the line before the line starting at off, -1
// at the file's first line.
func lineBefore(src []byte, off int) int {
	if off == 0 {
		return -1
	}
	return bytes.LastIndexByte(src[:off-1], '\n') + 1
}

// blankLineAt reports whether the line starting at off holds only
// whitespace; the line before the first one counts as blank.
func blankLineAt(src []byte, off int) bool {
	if off < 0 {
		return true
	}
	end := bytes.IndexByte(src[off:], '\n')
	if end < 0 {
		end = len(src) - off
	}
	return len(bytes.TrimSpace(src[off:off+end])) == 0
}

// haltStatement is the file's __halt_compiler() statement, nil without one.
func haltStatement(f *ast.File) *ast.HaltCompiler {
	for _, s := range f.Stmts {
		switch s := s.(type) {
		case *ast.HaltCompiler:
			return s
		case *ast.Namespace:
			for _, b := range s.Body {
				if h, ok := b.(*ast.HaltCompiler); ok {
					return h
				}
			}
		}
	}
	return nil
}

// lowerLine compiles __LINE__ to the source line it stands on, so code that
// reads it sees the .phn's line (design/line-map.md §2). One inside text
// another edit already rewrites is left to it.
func (e *emitter) lowerLine(f *ast.File) {
	ast.Inspect(f, func(n ast.Node) bool {
		if m, ok := n.(*ast.MagicConst); ok && m.Kind == token.T_LINE && !e.editedWithin(m.S) {
			e.replace(m.S, strconv.Itoa(e.lineOf(m.S.Start)))
		}
		return true
	})
}

// importSite is a free insertion of compiler imports.
type importSite struct {
	span ast.Span
	text string
}

// importSites places the compiler's imports where a person would write
// them, each on a line of its own (roadmap D11, line-map.md §2):
//
//   - into the file's class imports, after the neighbour it sorts after
//     (before the first one when it sorts first) if the block is sorted as
//     php-cs-fixer sorts, after the last class import otherwise;
//   - as a group of their own before the first function or constant import
//     when the file has only those (class imports come first);
//   - as a new block after the namespace statement in a file without
//     imports, a blank line before and after it;
//   - in a file without a namespace, after its own declare statement or
//     at its start, a blank line after it.
func (e *emitter) importSites(f *ast.File) []importSite {
	var names []string
	for fqcn, short := range e.imports {
		if short != "" && !e.ownImports[fqcn] {
			names = append(names, fqcn)
		}
	}
	if len(names) == 0 {
		return nil
	}
	sort.Slice(names, func(i, j int) bool { return compareImports(names[i], names[j]) < 0 })
	lines := func(ns []string) []string {
		out := make([]string, len(ns))
		for i, n := range ns {
			out[i] = "use " + n + ";"
		}
		return out
	}
	at := func(off int) ast.Span { return ast.Span{Start: off, End: off} }
	var classes, others []*ast.Use
	for _, st := range f.Stmts {
		if u, ok := st.(*ast.Use); ok {
			if u.Kind == ast.UseClass {
				classes = append(classes, u)
			} else {
				others = append(others, u)
			}
		}
	}
	switch {
	case len(classes) > 0:
		sorted := true
		for i := 1; i < len(classes); i++ {
			if compareImports(importKey(classes[i-1]), importKey(classes[i])) > 0 {
				sorted = false
			}
		}
		// Each name goes after the import it sorts after; names sorting
		// before the first import go before it.
		var first []string
		after := map[int][]string{}
		for _, n := range names {
			i := len(classes)
			if sorted {
				for j, u := range classes {
					if compareImports(importKey(u), n) > 0 {
						i = j
						break
					}
				}
			}
			if i == 0 {
				first = append(first, n)
			} else {
				after[i-1] = append(after[i-1], n)
			}
		}
		var sites []importSite
		if len(first) > 0 {
			indent := e.lineIndent(classes[0].S.Start)
			sites = append(sites, importSite{at(classes[0].S.Start), strings.Join(lines(first), "\n"+indent) + "\n" + indent})
		}
		for i, u := range classes {
			if ns := after[i]; len(ns) > 0 {
				indent := e.lineIndent(u.S.Start)
				sites = append(sites, importSite{at(e.statementLineEnd(u.S.End)), "\n" + indent + strings.Join(lines(ns), "\n"+indent)})
			}
		}
		return sites
	case len(others) > 0:
		indent := e.lineIndent(others[0].S.Start)
		return []importSite{{at(others[0].S.Start), strings.Join(lines(names), "\n"+indent) + "\n\n" + indent}}
	}
	block := strings.Join(lines(names), "\n")
	nsEnd := namespaceEnd(f)
	after := -1
	switch {
	case nsEnd >= 0:
		after = nsEnd
	case len(f.Stmts) > 0 && declaresFirst(f):
		after = f.Stmts[0].Span().End
	}
	if after < 0 {
		// At the start, before whatever the file opens with.
		return []importSite{{at(0), block + "\n\n"}}
	}
	end := e.statementLineEnd(after)
	if end == after && end < len(e.src) && e.src[end] != '\n' && e.src[end] != '\r' {
		// Code follows on the statement's line: it moves below the block.
		next := end
		for next < len(e.src) && (e.src[next] == ' ' || e.src[next] == '\t') {
			next++
		}
		return []importSite{{ast.Span{Start: end, End: next}, "\n\n" + block + "\n\n"}}
	}
	text := "\n\n" + block
	if !e.blankLineAfter(end) {
		text += "\n"
	}
	return []importSite{{at(end), text}}
}

// declaresFirst reports whether the file opens with a declare statement,
// which must stay its first statement.
func declaresFirst(f *ast.File) bool {
	_, ok := f.Stmts[0].(*ast.Declare)
	return ok
}

// statementLineEnd is where the line of a statement ending at off ends, when
// only whitespace and comments follow it there; off itself when more code
// follows on the line.
func (e *emitter) statementLineEnd(off int) int {
	toks := e.tokens()
	i := sort.Search(len(toks), func(i int) bool { return toks[i].Start >= off })
	for ; i < len(toks); i++ {
		t := toks[i]
		switch {
		case t.Kind == token.T_WHITESPACE:
			if nl := bytes.IndexByte(e.src[t.Start:t.End], '\n'); nl >= 0 {
				end := t.Start + nl
				if end > t.Start && e.src[end-1] == '\r' {
					end--
				}
				return end
			}
		case t.Kind == token.T_COMMENT:
			if bytes.HasSuffix(e.src[t.Start:t.End], []byte("\n")) {
				// A line comment holds its line break.
				end := t.End - 1
				if end > t.Start && e.src[end-1] == '\r' {
					end--
				}
				return end
			}
		case t.Kind == token.EOF:
			return t.Start
		case !t.Kind.IsTrivia():
			return off
		}
	}
	return len(e.src)
}

// blankLineAfter reports whether the line after the line break at off is
// blank (or the file ends there).
func (e *emitter) blankLineAfter(off int) bool {
	nl := bytes.IndexByte(e.src[off:], '\n')
	if nl < 0 {
		return true
	}
	rest := e.src[off+nl+1:]
	if end := bytes.IndexByte(rest, '\n'); end >= 0 {
		rest = rest[:end]
	}
	return len(bytes.TrimSpace(rest)) == 0
}

// importKey is the name an import statement sorts by: its first imported
// name, with a group's prefix.
func importKey(u *ast.Use) string {
	var parts []string
	if u.Prefix != nil {
		parts = append(parts, u.Prefix.Parts...)
	}
	if len(u.Items) > 0 {
		parts = append(parts, u.Items[0].Name.Parts...)
	}
	return strings.Join(parts, "\\")
}

// compareImports orders two imported names as php-cs-fixer's ordered_imports
// does by default: case-insensitively, a namespace separator read as a
// space (so `Foo\Bar` sorts before `FooBar`).
func compareImports(a, b string) int {
	norm := func(s string) string {
		return strings.ToLower(strings.ReplaceAll(strings.TrimPrefix(s, "\\"), "\\", " "))
	}
	return strings.Compare(norm(a), norm(b))
}

// namespaceEnd is the offset after the file's single unbraced namespace
// statement, -1 when the file has none, -2 when imports cannot be placed
// (braced or several namespaces: importShort then falls back to the FQCN).
func namespaceEnd(f *ast.File) int {
	end := -1
	for _, s := range f.Stmts {
		if ns, ok := s.(*ast.Namespace); ok {
			if ns.Braced || end != -1 {
				return -2
			}
			end = ns.S.End
		}
	}
	return end
}

// importShort returns the name a compiler-introduced class is called by in
// this file: its short name, imported with `use`, unless that name is taken
// by a user import or a class of the namespace, or imports cannot be placed
// — then the fully qualified name (roadmap D11).
func (e *emitter) importShort(fqcn string, res *program.Resolver) string {
	if e.imports == nil {
		e.imports = map[string]string{}
		e.ownImports = map[string]bool{}
	}
	if short, seen := e.imports[fqcn]; seen {
		if short == "" {
			return "\\" + fqcn
		}
		return short
	}
	short := fqcn[strings.LastIndex(fqcn, "\\")+1:]
	if strings.EqualFold(res.Scope().Prefix()+short, fqcn) {
		// The class belongs to this file's namespace: its short name is it.
		e.imports[fqcn] = short
		e.ownImports[fqcn] = true
		return short
	}
	taken := namespaceEnd(e.opts.File.AST) == -2
	for alias, target := range res.Scope().Imports() {
		if strings.EqualFold(target, fqcn) {
			// The file imports the class itself: use its name, add nothing.
			if written := importAlias(e.opts.File.AST, fqcn); written != "" {
				alias = written
			}
			e.imports[fqcn] = alias
			e.ownImports[fqcn] = true
			return alias
		}
		if strings.EqualFold(alias, short) {
			taken = true
		}
	}
	for other, s := range e.imports {
		if s == short && other != fqcn {
			taken = true
		}
	}
	if e.opts.Program.Class(res.Scope().Prefix()+short) != nil || e.qualifiedHead(short) {
		taken = true
	}
	if taken {
		e.imports[fqcn] = ""
		return "\\" + fqcn
	}
	e.imports[fqcn] = short
	return short
}

// qualifiedHead reports whether a qualified name the file writes, in code or
// in a docblock, begins with the segment short. An import of that short
// name would take the name over: PHP and PHPStan resolve the first segment
// of a qualified name through the file's imports, so after `use
// Random\Engine;` (the class the override-erasure rule widens a parameter
// to) the `Engine\Check` the programmer meant as a class of the current
// namespace becomes Random\Engine\Check. Only whole segments count
// (`Engines\X` does not begin with `Engine`); fully qualified and
// `namespace\` names and the names of use statements never go through an
// import. An unqualified name needs no check here: it names a class of the
// namespace, which importShort already looks up.
func (e *emitter) qualifiedHead(short string) bool {
	if e.qualifiedHeads == nil {
		e.qualifiedHeads = map[string]bool{}
		ast.Inspect(e.opts.File.AST, func(n ast.Node) bool {
			switch n := n.(type) {
			case *ast.Use:
				return false
			case *ast.Name:
				if n.Kind == ast.NameQualified && len(n.Parts) > 1 {
					e.qualifiedHeads[strings.ToLower(n.Parts[0])] = true
				}
			}
			return true
		})
		for _, doc := range docComment.FindAll(e.src, -1) {
			for _, m := range docQualifiedName.FindAllSubmatch(doc, -1) {
				e.qualifiedHeads[strings.ToLower(string(m[1]))] = true
			}
		}
	}
	return e.qualifiedHeads[strings.ToLower(short)]
}

var (
	docComment = regexp.MustCompile(`(?s)/\*\*.*?\*/`)
	// A relative qualified class name in a docblock: a segment not preceded
	// by a backslash, a name character or `$`, followed by a backslash.
	docQualifiedName = regexp.MustCompile(`(?:^|[^\\\w$])([A-Za-z_][A-Za-z0-9_]*)\\[A-Za-z_]`)
)

// importAlias is the name a file's own use statement gives fqcn, as
// written (the scope keeps it lower-cased), or "" when the file does not
// import it.
func importAlias(f *ast.File, fqcn string) string {
	alias := ""
	ast.Inspect(f, func(n ast.Node) bool {
		u, ok := n.(*ast.Use)
		if !ok {
			return alias == ""
		}
		for _, item := range u.Items {
			var parts []string
			if u.Prefix != nil {
				parts = append(parts, u.Prefix.Parts...)
			}
			parts = append(parts, item.Name.Parts...)
			if !strings.EqualFold(strings.Join(parts, "\\"), fqcn) {
				continue
			}
			if item.Alias != nil {
				alias = item.Alias.Name
			} else {
				alias = parts[len(parts)-1]
			}
		}
		return false
	})
	return alias
}

// declaresStrictTypes reports whether the first statement is a declare with
// a strict_types directive (PHP requires it to be first, so that is the only
// place to look).
func declaresStrictTypes(f *ast.File) bool {
	if len(f.Stmts) == 0 {
		return false
	}
	d, ok := f.Stmts[0].(*ast.Declare)
	if !ok {
		return false
	}
	for _, dir := range d.Directives {
		if strings.EqualFold(dir.Name.Name, "strict_types") {
			return true
		}
	}
	return false
}
